def valid_actuals():
    results = []
    for a in range(0, 31):
        for b in range(a, 31):
            c = 30 - a - b
            if c < b:
                continue
            if c < 0:
                continue
            # at least one box has >= 2 coins
            if max(a, b, c) < 2:
                continue
            # one box contains 6 more coins than another box
            diff_ok = False
            if a + 6 == b or a + 6 == c or b + 6 == c or b + 6 == a or c + 6 == a or c + 6 == b:
                diff_ok = True
            if not diff_ok:
                continue
            results.append((a, b, c))
    return results

actual_triples = valid_actuals()
print("Number of valid (sorted) actual triples:", len(actual_triples))
print("First few valid triples:", actual_triples[:10])

def bob_payoff(g, a_sorted):
    # g is tuple of 3 guesses, a_sorted is (x,y,z) sorted ascending
    # host chooses permutation of a_sorted to minimize sum of g_i where g_i <= a[perm[i]]
    min_pay = float('inf')
    for perm in permutations(a_sorted):
        total = 0
        for guess, actual in zip(g, perm):
            if guess <= actual:
                total += guess
        if total < min_pay:
            min_pay = total
    return min_pay

best_value = -1
best_guess = None
best_payoffs = {}  # to store V(g) for top guesses

print("\nSearching for optimal strategy...")
count = 0
for g1 in range(0, 31):
    for g2 in range(g1, 31):
        for g3 in range(g2, 31):
            g = (g1, g2, g3)
            min_over_actuals = float('inf')
            for a_sorted in actual_triples:
                pay = bob_payoff(g, a_sorted)
                if pay < min_over_actuals:
                    min_over_actuals = pay
                if min_over_actuals == 0:
                    break
            if min_over_actuals > best_value:
                best_value = min_over_actuals
                best_guess = g
                best_payoffs[g] = min_over_actuals
