print(f"\nTotal guess triples checked: {count}")
print("\nBest guess triple (sorted):", best_guess)
print("Maximum guaranteed coins:", best_value)
print("Minimum amount of money ($):", best_value * 1000)

# Show some top strategies
print("\nTop strategies:")
sorted_payoffs = sorted(best_payoffs.items(), key=lambda x: x[1], reverse=True)
for i, (g, payoff) in enumerate(sorted_payoffs[:10]):
